# =============================================================================
# Which paths wake which suite — the ONE map of tests/plan.py (CI, run-all.sh --changed, a worker's local run)
# =============================================================================
#   <suite> <glob|%group> …    tests/test-<suite>.sh runs when the diff touches a matching path (its own file is implied)
#   %group <glob|%group> …     a name for a set of globs, used on suite lines
#   @always <suite> …          in every plan
#   @full <glob> …             a path here makes the plan the full suite
#   @with <suite> <suite> …    when the first suite is planned, the others are planned too
# `*` matches any characters, `/` included. One line per suite; tests/test-plan.sh (python3 tests/plan.py --check) is red when a
# tracked file is in no line and not in tests/map-exclusions.txt, a glob matches nothing, a suite has no line, or a suite names
# (or runs, through imports and shell wiring) a file under plugins/ or tests/fixtures/ that its line does not cover.
# Editing a suite's line runs that suite (and @always); editing @always, @full or @with runs everything.
# A path in tests/map-exclusions.txt (the documents: READMEs, docs/, kb/, release notes) wakes no suite even when a line here matches
# it: CI tests code, not documents.
# A PR runs the tests of what it changed: a test script wakes its own suite (the scanners that read every test file run
# in the full run); skill and rule text (`skills/**.md`, `rules/*.md`) is in no whole-plugin group and wakes only the suites that
# read it, named on their lines; code wakes the suites that run it.
# Why: a PR runs the suites its diff reaches, and the scheduled full run catches the rest.
# =============================================================================

# every suite sources lib.sh, and lib.sh sources netguard.sh, capped.sh and plant.sh. The planner, its exclusion list and the runner are not
# here: tests/plan.py and tests/map-exclusions.txt wake `plan`, tests/run-all.sh wakes `plan` and `run-all`
@full tests/fixtures/lib.sh tests/fixtures/netguard.sh tests/fixtures/capped.sh tests/fixtures/plant.sh

# read EVERY tracked file, so no path can be what wakes them: the coverage guard (a file added anywhere is only checked by it)
# and cai-dat (its leak scan reads every file outside .git/ and tests/ for home paths, e-mails, public IPs, tokens and keys, and
# counts symlinks anywhere in the repository)
# and conflict-markers (it scans every tracked text file, tests/ included, for a committed merge-conflict marker)
@always plan cai-dat conflict-markers


# ── groups ──────────────────────────────────────────────────────────────────────────────────────────────────────────
# the branch/PR cores and what they import
%core plugins/vibemaestro-sdlc/gates/gate_common.py plugins/vibemaestro-sdlc/gates/pr_body.py plugins/vibemaestro-sdlc/scripts/sdlc_config.py plugins/vibemaestro-sdlc/scripts/messages.py plugins/vibemaestro-sdlc/scripts/current_state.py plugins/vibemaestro-sdlc/scripts/kb_index.py plugins/vibemaestro-sdlc/scripts/kb_plan.py plugins/vibemaestro-sdlc/scripts/intent_branch.py plugins/vibemaestro-sdlc/scripts/intent-branch.sh plugins/vibemaestro-sdlc/scripts/open_pr.py plugins/vibemaestro-sdlc/scripts/open-pr.sh
# everything the hook engine and kb.py load at run time: every script, the hooks. Not the rule text it delivers (the suites that
# read a rule name it), not the skills (the engine only checks that skills/<name>/SKILL.md exists) and not the manifest
# (rule_packs.py reads a DEPENDENT plugin's only)
%runtime plugins/vibemaestro-sdlc/scripts/* plugins/vibemaestro-sdlc/gates/gate_common.py plugins/vibemaestro-sdlc/gates/pr_body.py plugins/vibemaestro-sdlc/hooks/* plugins/vibemaestro-sdlc/templates/*
%gates plugins/vibemaestro-sdlc/gates/* %core
%batons plugins/vibemaestro-sdlc/batons/* plugins/vibemaestro-sdlc/scripts/baton.py plugins/vibemaestro-sdlc/scripts/baton-launcher.py plugins/vibemaestro-sdlc/templates/baton-script.sh
# a whole plugin's code: suites that validate, install, scan or copy-and-check all of it. Its code directories are listed one by
# one, so skill and rule text is not in the group and a new top-level directory is unmapped until it gets a line (the guard)
%sdlc plugins/vibemaestro-sdlc/.claude-plugin/* plugins/vibemaestro-sdlc/CONTRACT.md plugins/vibemaestro-sdlc/batons/* plugins/vibemaestro-sdlc/gates/* plugins/vibemaestro-sdlc/hooks/* plugins/vibemaestro-sdlc/scripts/* plugins/vibemaestro-sdlc/templates/*
%brain plugins/vibemaestro-brain/.claude-plugin/* plugins/vibemaestro-brain/bin/* plugins/vibemaestro-brain/hooks/* plugins/vibemaestro-brain/scripts/* plugins/vibemaestro-brain/templates/*
# the planner reads a suite's `$X/hooks/hooks.json` (sdlc's, through a variable it cannot resolve) as every hooks/hooks.json, so
# since B1.2 these suites also "reach" the brain's hooks and what they import; they never run them (an over-approximation)
%brain-hooks plugins/vibemaestro-brain/hooks/hooks.json plugins/vibemaestro-brain/scripts/brain.py plugins/vibemaestro-brain/scripts/brain_hook.py plugins/vibemaestro-brain/scripts/brain_store.py plugins/vibemaestro-brain/scripts/brain_cost.py plugins/vibemaestro-brain/scripts/brain_matrix.py
# what the brain's code runs of vibemaestro-sdlc (its dependency): the loader, the sensitive-value filter brain_store.py calls, the manifest
%sdlc-for-brain plugins/vibemaestro-sdlc/.claude-plugin/* plugins/vibemaestro-sdlc/scripts/sdlc_config.py plugins/vibemaestro-sdlc/scripts/messages.py plugins/vibemaestro-sdlc/gates/pr_sensitive.py plugins/vibemaestro-sdlc/gates/gate_common.py
# the sdlc hooks.json and what its hooks import (brain-matrix's probe runs the sdlc SessionStart; the planner reads brain-owner's
# `$X/hooks/hooks.json` as the sdlc one too)
%sdlc-hooks plugins/vibemaestro-sdlc/hooks/hooks.json plugins/vibemaestro-sdlc/scripts/session-start.py plugins/vibemaestro-sdlc/scripts/vsdlc.py plugins/vibemaestro-sdlc/scripts/hookout.py plugins/vibemaestro-sdlc/scripts/baton.py plugins/vibemaestro-sdlc/scripts/current_state.py plugins/vibemaestro-sdlc/scripts/pre-bash.py plugins/vibemaestro-sdlc/scripts/pre-edit.py plugins/vibemaestro-sdlc/scripts/rule_packs.py plugins/vibemaestro-sdlc/scripts/rules.py
%hub tests/fixtures/hub-shaped/*
%flow tests/fixtures/flow.sh tests/fixtures/ports.sh
# the repository's own sdlc config: read by kb.py run from the repo root, and by suites that copy the whole repository
%repo-config .vibemaestro/*

